/** Public entry point — the only module consumers/docs should import from. */

export { DataGridToolbar, type DataGridToolbarProps } from "./toolbar";
export { DataGridSearch, type DataGridSearchProps } from "./search";
export { DataGridFilterMenu, type DataGridFilterMenuProps } from "./filter-menu";
export { DataGridColumnsMenu, type DataGridColumnsMenuProps } from "./columns-menu";
export { operatorsForColumnType, operatorLabel, operatorHasValue } from "./operators-for-column-type";
export { DataGridHeaderFilter, type DataGridHeaderFilterProps } from "./header-filter";

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";
import { useDataGridInstanceId, GRID_ATTR } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Props for {@link DataGridToolbar}. */
export type DataGridToolbarProps = {
  className?: string;
  children?: ReactNode;
};

/**
 * Flex frame for the grid's toolbar slots (search, filter menu, columns menu, custom buttons).
 * Consumers place it above `<DataGridRoot>`, inside the same `<DataGridProvider>`, so its children
 * share the grid's store.
 */
export function DataGridToolbar(props: DataGridToolbarProps): ReactNode {
  const { className, children } = props;
  const instanceId = useDataGridInstanceId();
  return (
    <div
      {...{ [GRID_ATTR.instance]: instanceId }}
      data-grid-toolbar=""
      className={cn("flex items-center gap-2 overflow-x-auto border-b border-border bg-background px-2 py-1.5", className)}
    >
      {children}
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { ChevronDown, ChevronUp, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { useDebouncedInput } from "@/registry/default/components/gridcn/use-debounce";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import { Button } from "@/components/ui/button";
import {
  useDataGridActions,
  useDataGridLabels,
  useDataGridScrollToCellAt,
  useDataGridSearchText,
} from "@/registry/default/components/data-grid/data-grid";
import {
  useDataGridInstanceId,
  useDataGridStoreApi,
  GRID_ATTR,
  isComposingKey,
  useDataGridInputDebounce,
  useDataGridSearchCapped,
  useDataGridSearchMatches,
} from "@/registry/default/components/data-grid/data-grid-sdk";

/** Props for {@link DataGridSearch}. */
export type DataGridSearchProps = {
  className?: string;
  placeholder?: string;
  /**
   * Debounce (ms) between typing and the store's `searchText` update. Default: the provider's `inputDebounceMs` (200).
   */
  debounceMs?: number;
  /**
   * "Feels native" bridge: mod+F (Ctrl+F / Cmd+F) with focus inside this grid or its
   * toolbar focuses/selects this input instead of opening the browser's find bar. Native
   * find-in-page can't work over virtualized rows (only the window's rendered rows exist in the
   * DOM), and our search already scrolls to matches — this makes mod+F reach for it directly.
   * Default `true` — when this component is mounted and focus is inside this grid, mod+F
   * unambiguously means "search this grid"; with several grids on one page, mod+F always reaches
   * the grid that holds focus, never a sibling grid's search. The listener is grid-scoped (never
   * window/document globally): focus anywhere else on the page is completely untouched, so a page's own search UI
   * or the browser's native find behave exactly as if this prop didn't exist. Pass `false` to
   * disable and always defer to the browser's native find.
   */
  captureFindShortcut?: boolean;
};

/** True when `target` sits in this grid's DOM, or in a `[data-grid-toolbar]` that holds `input`; never in a sibling grid. */
function isInsideGridScope(target: EventTarget | null, instanceId: string, input: HTMLElement | null): boolean {
  if (!(target instanceof Element)) return false;
  if (target.closest(`[${GRID_ATTR.instance}="${instanceId}"]`) !== null) return true;
  const toolbar = target.closest(`[${GRID_ATTR.toolbar}]`);
  return toolbar !== null && input !== null && toolbar.contains(input);
}

/**
 * Quick-search input: debounced write to the store's `searchText`, a match-count badge
 * ("3/17"), and prev/next controls that step through matches in row-major order, moving the
 * active cell to the match and scrolling it into view. Enter/Shift+Enter mirror the buttons;
 * Escape clears the field and the store's search text.
 */
export function DataGridSearch(props: DataGridSearchProps): ReactNode {
  const { className, placeholder, captureFindShortcut = true, debounceMs } = props;
  const labels = useDataGridLabels();
  const actions = useDataGridActions();
  const searchText = useDataGridSearchText();
  const matches = useDataGridSearchMatches();
  const capped = useDataGridSearchCapped();
  const scrollToCell = useDataGridScrollToCellAt();
  const instanceId = useDataGridInstanceId();
  const storeApi = useDataGridStoreApi();

  const providerDebounceMs = useDataGridInputDebounce();
  // the input value is decoupled from the store's debounced searchText, so typing never stalls.
  const input = useDebouncedInput(searchText, (text) => actions.setSearch(text), { delayMs: debounceMs ?? providerDebounceMs });
  const [matchIndex, setMatchIndex] = useState(0);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const jumpOnCommitRef = useRef<string | null>(null);

  // restart navigation at the first hit during render, not in an effect: a new query must not paint the old index
  const { matchCase, wholeCell } = storeApi.getState().searchOptions;
  const queryKey = `${JSON.stringify(searchText)}${matchCase}${wholeCell}`;
  const [lastQueryKey, setLastQueryKey] = useState(queryKey);
  if (lastQueryKey !== queryKey) {
    setLastQueryKey(queryKey);
    setMatchIndex(0);
  }

  // No DOM ancestor spans toolbar and root, so listen on document and gate by instance id or the toolbar holding this input.
  useEffect(() => {
    if (!captureFindShortcut) return;

    function onKeyDown(event: KeyboardEvent) {
      const isFind = (event.metaKey || event.ctrlKey) && !event.altKey && event.key.toLowerCase() === "f";
      if (!isFind || event.defaultPrevented || !isInsideGridScope(event.target, instanceId, inputRef.current)) return;
      event.preventDefault();
      const input = inputRef.current;
      if (!input) return;
      if (document.activeElement === input) {
        input.select();
      } else {
        input.focus();
      }
    }

    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [captureFindShortcut, instanceId]);

  const goToMatch = useCallback(
    (index: number) => {
      const { searchMatches, visibleColumns: columns } = storeApi.getState();
      if (searchMatches.length === 0) return;
      const wrapped = ((index % searchMatches.length) + searchMatches.length) % searchMatches.length;
      setMatchIndex(wrapped);
      const match = searchMatches[wrapped]!; // wrapped is modulo'd into [0, searchMatches.length)
      const col = columns.findIndex((c) => c.id === match.columnId);
      if (col === -1) return;
      const coord = { col, row: match.row };
      actions.setActiveCellAt(coord);
      scrollToCell(coord);
    },
    [actions, scrollToCell, storeApi],
  );

  // A controlled parent applies the committed text later, so the first match is known only once searchText has caught up.
  useEffect(() => {
    if (jumpOnCommitRef.current === null || jumpOnCommitRef.current !== searchText) return;
    jumpOnCommitRef.current = null;
    goToMatch(0);
  }, [searchText, matches, goToMatch]);

  const onKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (isComposingKey(event)) return;
    if (event.key === "Escape") {
      event.preventDefault();
      jumpOnCommitRef.current = null;
      input.cancel();
      actions.setSearch("");
    } else if (event.key === "Enter") {
      event.preventDefault();
      if (input.inputValue !== searchText) {
        jumpOnCommitRef.current = input.inputValue;
        input.flush();
      } else goToMatch(matchIndex + (event.shiftKey ? -1 : 1));
    }
  };

  const hasMatches = matches.length > 0;
  const shownIndex = Math.min(matchIndex, matches.length - 1);

  return (
    <div data-grid-search="" className={cn("flex h-8 items-center gap-1", className)}>
      <InputGroup className="w-72" {...{ [GRID_ATTR.keepFocus]: "" }}>
        <InputGroupAddon align="inline-start">
          <Search />
        </InputGroupAddon>
        <InputGroupInput
          ref={inputRef}
          {...input.inputProps}
          onChange={(event) => {
            jumpOnCommitRef.current = null;
            input.inputProps.onChange(event);
          }}
          onKeyDown={onKeyDown}
          placeholder={placeholder ?? labels.toolbar.searchPlaceholder}
          aria-label={labels.toolbar.searchAriaLabel}
        />
        {searchText.trim() !== "" && (
          <InputGroupAddon align="inline-end">
            <span data-grid-search-count="" role="status" aria-live="polite" className="min-w-fit text-xs tabular-nums">
              {hasMatches
                ? capped
                  ? labels.toolbar.searchMatchesCapped(shownIndex + 1)
                  : labels.toolbar.searchMatches(shownIndex + 1, matches.length)
                : labels.toolbar.searchNoMatches}
            </span>
          </InputGroupAddon>
        )}
      </InputGroup>
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label={labels.toolbar.searchPreviousMatch}
        disabled={!hasMatches}
        onClick={() => goToMatch(matchIndex - 1)}
      >
        <ChevronUp />
      </Button>
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label={labels.toolbar.searchNextMatch}
        disabled={!hasMatches}
        onClick={() => goToMatch(matchIndex + 1)}
      >
        <ChevronDown />
      </Button>
    </div>
  );
}

import type { FilterGroup, FilterNode } from "@/registry/default/components/data-grid/data-grid";
import { groupChildren, isFilterGroup } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Applies `edit` to the child list of the group `parentId`, or to the top level when `parentId` is undefined. */
function editList(nodes: readonly FilterNode[], parentId: string | undefined, edit: (list: readonly FilterNode[]) => FilterNode[]): FilterNode[] {
  if (parentId === undefined) return edit(nodes);
  return nodes.map((node) => {
    if (!isFilterGroup(node)) return node;
    return node.filterId === parentId ? { ...node, filters: edit(groupChildren(node)) } : { ...node, filters: editList(groupChildren(node), parentId, edit) };
  });
}

export function updateNode(nodes: readonly FilterNode[], filterId: string, update: (node: FilterNode) => FilterNode): FilterNode[] {
  return nodes.map((node) => {
    if (node.filterId === filterId) return update(node);
    return isFilterGroup(node) ? { ...node, filters: updateNode(groupChildren(node), filterId, update) } : node;
  });
}

/** Removes a node at any level and drops a group that the removal leaves empty. */
export function removeNode(nodes: readonly FilterNode[], filterId: string): FilterNode[] {
  const next: FilterNode[] = [];
  for (const node of nodes) {
    if (node.filterId === filterId) continue;
    if (!isFilterGroup(node)) {
      next.push(node);
      continue;
    }
    const children = groupChildren(node);
    const kept = removeNode(children, filterId);
    if (kept.length > 0 || children.length === 0) next.push({ ...node, filters: kept });
  }
  return next;
}

export function appendChild(nodes: readonly FilterNode[], parentId: string | undefined, child: FilterNode): FilterNode[] {
  return editList(nodes, parentId, (list) => [...list, child]);
}

/** Moves a child inside one sibling list; the move never changes the level. */
export function moveSibling(nodes: readonly FilterNode[], parentId: string | undefined, fromIndex: number, toIndex: number): FilterNode[] {
  return editList(nodes, parentId, (list) => {
    const next = list.slice();
    const [moved] = next.splice(fromIndex, 1);
    if (moved === undefined) return next;
    next.splice(toIndex, 0, moved);
    return next;
  });
}

/** The join a new group takes: the opposite of its parent's, with the top level counting as "and". */
export function oppositeJoin(parent: FilterGroup | undefined): FilterGroup["join"] {
  return parent?.join === "or" ? "and" : "or";
}

export type NodeLocation = { parentId: string | undefined; siblings: readonly FilterNode[]; index: number };

/** Finds the node and the sibling list that holds it. */
export function locateNode(nodes: readonly FilterNode[], filterId: string, parentId?: string): NodeLocation | undefined {
  const index = nodes.findIndex((node) => node.filterId === filterId);
  if (index !== -1) return { parentId, siblings: nodes, index };
  for (const node of nodes) {
    if (!isFilterGroup(node)) continue;
    const found = locateNode(groupChildren(node), filterId, node.filterId);
    if (found) return found;
  }
  return undefined;
}

"use client";

import { useCallback, useEffect, useRef, useState, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from "react";
import { AutoScroller } from "@dnd-kit/dom";
import { DragDropProvider } from "@dnd-kit/react";
import { useSortable } from "@dnd-kit/react/sortable";
import { Filter, GripVertical, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridCellTypes,
  useDataGridFilterState,
  useDataGridLabels,
  useDataGridVisibleColumns,
  type AnyColumnDef,
  type DataGridLabels,
  type FilterGroup,
  type FilterNode,
  type FilterOperator,
  type FilterSpec,
} from "@/registry/default/components/data-grid/data-grid";
import {
  MAX_FILTER_GROUP_DEPTH,
  columnLabelText,
  countFilterSpecs,
  forEachFilterSpec,
  isDev,
  isFilterGroup,
  operatorsForColumnType,
  resolveFilterOperators,
  useDataGridStoreApi,
} from "@/registry/default/components/data-grid/data-grid-sdk";
import { appendChild, locateNode, moveSibling, oppositeJoin, removeNode, updateNode } from "./filter-tree-edit";
import { emptyValueFor, operatorHasValue, operatorLabel } from "./operators-for-column-type";
import { DataGridFilterValueInput } from "./filter-value-input";

/** Props for {@link DataGridFilterMenu}. */
export type DataGridFilterMenuProps = {
  className?: string;
  /**
   * Source the column options from every column (including hidden ones) instead of only the visible
   * columns; default false. Without it, a filter set on a hidden column (programmatically or via a
   * restored layout) keeps applying but renders with no column context and logs a dev-time warning.
   */
  allColumns?: boolean;
  /**
   * Replaces the operator list the menu offers per column. Resolution order: this prop (a returned
   * `undefined` falls through), then the column's own `filterOperators`, then the built-in
   * `operatorsForColumnType` for its `type`.
   */
  operatorsForColumn?: (column: AnyColumnDef) => readonly FilterOperator[] | undefined;
};

/** dnd-kit drag payload for a filter row or group: compiler-checked in place of `Record<string, any>`. */
type FilterRowDragData = { index: number; filterId: string };

/** What a row or group needs from the menu root. */
type FilterMenuContext = {
  columns: readonly AnyColumnDef[];
  filterableColumns: readonly AnyColumnDef[];
  operatorsFor: (column: AnyColumnDef | undefined) => readonly FilterOperator[];
  labels: DataGridLabels;
  onUpdate: (filterId: string, next: Partial<FilterSpec>) => void;
  onJoinChange: (filterId: string, join: FilterGroup["join"]) => void;
  onRemove: (filterId: string) => void;
  onAddFilter: (parent: FilterGroup | undefined) => void;
  onAddGroup: (parent: FilterGroup | undefined) => void;
  onReorder: (parentId: string | undefined, fromIndex: number, toIndex: number, filterId: string) => void;
  gripRef: (filterId: string, el: HTMLButtonElement | null) => void;
  lockRootScroll: () => void;
  unlockRootScroll: () => void;
};

/**
 * Popover listing the filter tree. The top level is a list of rows and groups joined by "and"; a
 * group is a bordered box with its own rows; each row after the first shows an "And"/"Or" select
 * that sets the join of the whole group. Every row and group has a drag handle and a trash
 * icon-button; a row adds a field select, an operator select, and a typed value input. Footers hold
 * "Add filter" and "Add group" (a group nests one more group at most). Built from this repo's own
 * Base UI components. Reordering uses `@dnd-kit/react`'s sortable primitives (handle-initiated
 * pointer drag with a lifted-row overlay feel via `isDragSource` and a landing line at the target
 * slot), plus a plain ArrowUp/ArrowDown-on-drag handle fallback that always wins over the library's
 * own keyboard sensor (see `useNodeSortable`). Nodes are keyed by `filterId` (stable identity independent of
 * array position) since multiple rows on the same column are allowed and meaningful; a reorder moves
 * a node among its siblings only and persists through `setFilters`.
 */
export function DataGridFilterMenu(props: DataGridFilterMenuProps): ReactNode {
  const { className, allColumns = false, operatorsForColumn } = props;
  const actions = useDataGridActions();
  const storeApi = useDataGridStoreApi();
  const filters = useDataGridFilterState();
  const visibleColumns = useDataGridVisibleColumns();
  const gridColumns = useDataGridAllColumns();
  const columns = allColumns ? gridColumns : visibleColumns;
  const labels = useDataGridLabels();
  const cellTypes = useDataGridCellTypes();
  const filterableColumns = columns.filter((c) => c.filterable !== false);
  const rowCount = countFilterSpecs(filters);

  // per-column operator list: this prop > the column's filterOperators > the cell type's declared operators > the name-based type default
  const operatorsFor = useCallback(
    (column: AnyColumnDef | undefined): readonly FilterOperator[] => {
      if (!column) return operatorsForColumnType(undefined);
      return operatorsForColumn?.(column) ?? resolveFilterOperators(column, column.type ? cellTypes[column.type] : undefined);
    },
    [operatorsForColumn, cellTypes],
  );

  // A filter on a column outside the menu's option list (a hidden column by default, or one no
  // longer in the grid) still applies to the view but renders with no column context and no picker
  // entry to re-target it — warn in dev and point at the fix.
  useEffect(() => {
    if (!isDev()) return;
    const listed = new Set(columns.map((c) => c.id));
    const orphans: FilterSpec[] = [];
    forEachFilterSpec(filters, (f) => {
      if (!listed.has(f.columnId)) orphans.push(f);
    });
    if (orphans.length === 0) return;
    const ids = Array.from(new Set(orphans.map((f) => f.columnId)));
    console.warn(
      `[data-grid-toolbar] DataGridFilterMenu: ${orphans.length} filter row(s) target column(s) missing from the menu's column list (${ids.join(", ")}); pass allColumns to manage hidden-column filters here`,
    );
  }, [filters, columns]);

  const [announcement, setAnnouncement] = useState("");
  const gripRefs = useRef(new Map<string, HTMLButtonElement | null>());
  const addButtonRef = useRef<HTMLButtonElement>(null);
  const pendingFocusFilterIdRef = useRef<string | null>(null);
  const idsBeforeAddRef = useRef<Set<string> | null>(null);

  // At drag end the browser re-focuses the drag handle and re-centers it, which jumps the page.
  const rootScrollLockRef = useRef<(() => void) | null>(null);
  const lockRootScroll = useCallback(() => {
    if (rootScrollLockRef.current) return;
    const y = window.scrollY;
    const onScroll = () => {
      if (window.scrollY !== y) window.scrollTo(0, y);
    };
    document.addEventListener("scroll", onScroll, true);
    rootScrollLockRef.current = () => {
      document.removeEventListener("scroll", onScroll, true);
      rootScrollLockRef.current = null;
    };
  }, []);
  const unlockRootScroll = useCallback(() => rootScrollLockRef.current?.(), []);
  const draggingRef = useRef(false);

  useEffect(() => {
    const before = idsBeforeAddRef.current;
    if (!before) return;
    idsBeforeAddRef.current = null;
    let added: string | undefined;
    forEachFilterSpec(filters, (f) => {
      if (added === undefined && f.filterId && !before.has(f.filterId)) added = f.filterId;
    });
    const row = added === undefined ? null : gripRefs.current.get(added)?.closest("[data-grid-filter-row]");
    row?.querySelector<HTMLElement>('[role="combobox"]')?.focus({ preventScroll: true });
  }, [filters]);

  useEffect(() => {
    const pendingId = pendingFocusFilterIdRef.current;
    if (!pendingId) return;
    pendingFocusFilterIdRef.current = null;
    (gripRefs.current.get(pendingId) ?? addButtonRef.current)?.focus({ preventScroll: true });
  }, [filters]);

  const releaseDragRafRef = useRef(0);
  useEffect(
    () => () => {
      unlockRootScroll();
      cancelAnimationFrame(releaseDragRafRef.current);
    },
    [unlockRootScroll],
  );

  const rememberFilterIds = () => {
    const ids = new Set<string>();
    forEachFilterSpec(latest(), (f) => f.filterId && ids.add(f.filterId));
    idsBeforeAddRef.current = ids;
  };

  const newRow = (): FilterSpec | undefined => {
    const first = filterableColumns[0];
    if (!first) return undefined;
    const operator = operatorsFor(first)[0]!; // always non-empty (TEXT_OPERATORS is the floor)
    return { columnId: first.id, operator, value: emptyValueFor(operator) };
  };

  const reorderAnnouncement = (next: readonly FilterNode[], filterId: string, toIndex: number): string | undefined => {
    const at = locateNode(next, filterId);
    const moved = at?.siblings[at.index];
    if (!at || !moved) return undefined;
    let label: string;
    if (isFilterGroup(moved)) label = labels.toolbar.filterGroupName;
    else {
      const column = columns.find((c) => c.id === moved.columnId);
      label = column ? columnLabelText(column) : moved.columnId;
    }
    return labels.toolbar.filterReorderAnnouncement(label, toIndex + 1, at.siblings.length);
  };

  // Handlers read the live tree: a debounced value commit from an older render must not overwrite a newer edit.
  const latest = () => storeApi.getState().filterState;

  const context: FilterMenuContext = {
    columns,
    filterableColumns,
    operatorsFor,
    labels,
    onUpdate: (filterId, next) => actions.setFilters(updateNode(latest(), filterId, (node) => ({ ...node, ...next }) as FilterNode)),
    onJoinChange: (filterId, join) => actions.setFilters(updateNode(latest(), filterId, (node) => ({ ...node, join }) as FilterNode)),
    onRemove: (filterId) => {
      const current = latest();
      const at = locateNode(current, filterId);
      actions.setFilters(removeNode(current, filterId));
      // focus follows deletion: a sibling's drag handle, else the Add button.
      // A sole row takes its group with it: walk up to the first level that keeps a sibling.
      let near = at;
      while (near && near.siblings.length === 1 && near.parentId) near = locateNode(current, near.parentId);
      const nextFocusId = near && (near.siblings[near.index + 1]?.filterId ?? near.siblings[near.index - 1]?.filterId);
      if (nextFocusId) pendingFocusFilterIdRef.current = nextFocusId;
      else requestAnimationFrame(() => addButtonRef.current?.focus({ preventScroll: true }));
    },
    onAddFilter: (parent) => {
      const row = newRow();
      if (row) rememberFilterIds();
      if (row) actions.setFilters(appendChild(latest(), parent?.filterId, row));
    },
    onAddGroup: (parent) => {
      const row = newRow();
      if (row) rememberFilterIds();
      if (row) actions.setFilters(appendChild(latest(), parent?.filterId, { join: oppositeJoin(parent), filters: [row] }));
    },
    onReorder: (parentId, fromIndex, toIndex, filterId) => {
      if (fromIndex === toIndex) return;
      const next = moveSibling(latest(), parentId, fromIndex, toIndex);
      actions.setFilters(next);
      pendingFocusFilterIdRef.current = filterId;
      setAnnouncement(reorderAnnouncement(next, filterId, toIndex) ?? "");
    },
    gripRef: (filterId, el) => {
      gripRefs.current.set(filterId, el);
    },
    lockRootScroll: () => {
      draggingRef.current = true;
      lockRootScroll();
    },
    unlockRootScroll: () => {
      // Escape cancels the drag; the popover must see it as still dragging, or it closes with the cancel.
      releaseDragRafRef.current = requestAnimationFrame(() => (draggingRef.current = false));
      unlockRootScroll();
    },
  };

  const noColumns = filterableColumns.length === 0;

  return (
    <Popover
      onOpenChange={(open, details) => {
        if (open) draggingRef.current = false;
        if (details.reason === "escape-key" && draggingRef.current) details.cancel();
      }}
    >
      <PopoverTrigger
        render={
          <Button type="button" variant="outline" size="sm" className={cn("relative", className)} aria-label={labels.toolbar.filterAriaLabel}>
            <Filter />
            {labels.toolbar.filter}
            {rowCount > 0 && (
              <Badge data-grid-filter-count="" variant="secondary" className="ms-1">
                {rowCount}
              </Badge>
            )}
          </Button>
        }
      />
      <PopoverContent align="start" className="flex w-full min-w-[min(26.25rem,calc(100vw-2rem))] max-w-[calc(100vw-2rem)] flex-col gap-3.5 p-4">
        <div data-grid-filter-menu="" className="flex flex-col gap-3.5">
          <h4 className="font-medium leading-none text-muted-foreground">{labels.toolbar.filter}</h4>
          {filters.length === 0 && <p className="text-sm text-muted-foreground">{labels.toolbar.noFiltersApplied}</p>}
          <div aria-live="polite" role="status" className="sr-only">
            {announcement}
          </div>
          {filters.length > 0 && <FilterList nodes={filters} parent={undefined} depth={0} path="" ctx={context} className="max-h-75 overflow-y-auto" />}
          <div className="flex w-full items-center gap-2">
            <Button type="button" ref={addButtonRef} onClick={() => context.onAddFilter(undefined)} disabled={noColumns}>
              {labels.toolbar.addFilter}
            </Button>
            <Button type="button" variant="outline" onClick={() => context.onAddGroup(undefined)} disabled={noColumns}>
              {labels.toolbar.addFilterGroup}
            </Button>
            {filters.length > 0 && (
              <Button type="button" variant="outline" onClick={() => actions.setFilters([])}>
                {labels.toolbar.clearFilters}
              </Button>
            )}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

type FilterListProps = {
  nodes: readonly FilterNode[];
  /** The group that owns the list; undefined for the top level, whose connector is "and". */
  parent: FilterGroup | undefined;
  /** Group levels above this list: 0 for the top level. */
  depth: number;
  /** Dotted 1-based group numbers from the top level to this list; "" for the top level. */
  path: string;
  ctx: FilterMenuContext;
  className?: string;
};

type DragSlot = { fromIndex: number; toIndex: number };

/** The edge of the node at the target slot where the dragged node lands. */
function dropEdgeAt(index: number, slot: DragSlot | null): DropEdge | undefined {
  if (!slot || slot.fromIndex === slot.toIndex || index !== slot.toIndex) return undefined;
  return slot.toIndex < slot.fromIndex ? "before" : "after";
}

/** One sibling list with its own drag context, so a drag never leaves its level. */
function FilterList(props: FilterListProps): ReactNode {
  const { nodes, parent, depth, path, ctx, className } = props;
  const join: FilterGroup["join"] = parent?.join === "or" ? "or" : "and";
  const parentId = parent?.filterId;
  const [slot, setSlot] = useState<DragSlot | null>(null);
  return (
    <DragDropProvider<FilterRowDragData>
      // The popover portals to body, so AutoScroller would scroll the page near a viewport edge.
      plugins={(defaults) => defaults.filter((p) => p !== AutoScroller)}
      onDragStart={(event) => {
        ctx.lockRootScroll();
        const fromIndex = event.operation.source?.data?.index;
        if (fromIndex !== undefined) setSlot({ fromIndex, toIndex: fromIndex });
      }}
      onDragOver={(event) => {
        const fromIndex = event.operation.source?.data?.index;
        const toIndex = event.operation.target?.data?.index;
        setSlot(fromIndex === undefined || toIndex === undefined ? null : { fromIndex, toIndex });
      }}
      onDragEnd={(event) => {
        ctx.unlockRootScroll();
        setSlot(null);
        if (event.canceled) return;
        const sourceData = event.operation.source?.data;
        const targetData = event.operation.target?.data;
        const fromIndex = sourceData?.index;
        const toIndex = targetData?.index;
        const filterId = sourceData?.filterId;
        if (fromIndex === undefined || toIndex === undefined || !filterId) return;
        ctx.onReorder(parentId, fromIndex, toIndex, filterId);
      }}
    >
      <div role="list" className={cn("flex flex-col gap-2 p-1", className)}>
        {nodes.map((node, index) => {
          const position = { index, total: nodes.length, parentId, join, path, dropEdge: dropEdgeAt(index, slot), ctx };
          if (isFilterGroup(node)) {
            const ordinal = nodes.slice(0, index + 1).filter(isFilterGroup).length;
            const groupPath = path ? `${path}.${ordinal}` : String(ordinal);
            return <FilterGroupBox key={node.filterId} group={node} depth={depth + 1} groupPath={groupPath} {...position} />;
          }
          return (
            <FilterRow key={node.filterId} filter={node} {...position} />
          );
        })}
      </div>
    </DragDropProvider>
  );
}

/** The first cell of a row or group: "Where" on the first, a select that sets the group's join after it; the top level is always "and". */
function ConnectorCell(props: { index: number; join: FilterGroup["join"]; parentId: string | undefined; path: string; ctx: FilterMenuContext }): ReactNode {
  const { index, join, parentId, path, ctx } = props;
  const { labels } = ctx;
  const items = [
    { value: "and", label: labels.toolbar.filterConnectorAnd },
    { value: "or", label: labels.toolbar.filterConnectorOr },
  ];
  const connector =
    parentId === undefined || index === 0 ? undefined : (
      <Select
        items={items}
        value={join}
        onValueChange={(value) => {
          if (value === null) return;
          ctx.onJoinChange(parentId, value as FilterGroup["join"]);
        }}
      >
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterGroupJoinAriaLabel(index + 1, path)}>
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {items.map((item) => (
            <SelectItem key={item.value} value={item.value}>
              {item.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  return (
    <div className="flex h-8 min-w-18 items-center justify-center text-center">
      {connector ?? <span className="text-sm text-muted-foreground">{index === 0 ? labels.toolbar.filterWhere : labels.toolbar.filterConnectorAnd}</span>}
    </div>
  );
}

type DropEdge = "before" | "after";

/** The line that shows where the dragged node lands, on the edge of the target node. */
function DropIndicator(props: { edge: DropEdge }): ReactNode {
  return (
    <div
      aria-hidden
      data-grid-filter-drop-indicator=""
      data-edge={props.edge}
      className={cn(
        "pointer-events-none absolute inset-x-0 z-20 h-1 rounded-full bg-primary ring-2 ring-background motion-safe:animate-in motion-safe:fade-in-0 motion-safe:duration-150",
        props.edge === "before" ? "-top-1.5" : "-bottom-1.5",
      )}
    />
  );
}

type NodePosition = { index: number; total: number; parentId: string | undefined; join: FilterGroup["join"]; path: string; dropEdge: DropEdge | undefined; ctx: FilterMenuContext };

/** Pointer drag through `useSortable`; ArrowUp/ArrowDown and Backspace/Delete on the handle win over dnd-kit's own keyboard sensor. */
function useNodeSortable(filterId: string, position: NodePosition) {
  const { index, total, parentId, ctx } = position;
  // No plugins: dnd-kit's optimistic DOM moves fight React's re-render after a drop; `onGripKeyDown` is the keyboard path.
  const sortable = useSortable<FilterRowDragData>({ id: filterId, index, data: { index, filterId }, plugins: [] });

  const onGripKeyDown = (event: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (event.key === "Backspace" || event.key === "Delete") {
      event.preventDefault();
      event.stopPropagation(); // wins over dnd-kit's keyboard sensor regardless of library support
      ctx.onRemove(filterId);
      return;
    }
    if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;
    event.preventDefault();
    event.stopPropagation(); // wins over dnd-kit's keyboard sensor regardless of library support
    const target = index + (event.key === "ArrowUp" ? -1 : 1);
    if (target < 0 || target >= total) return;
    ctx.onReorder(parentId, index, target, filterId);
  };

  return { ...sortable, onGripKeyDown };
}

type GripButtonProps = {
  label: string;
  isDragSource: boolean;
  handleRef: (el: HTMLButtonElement | null) => void;
  gripRef: (el: HTMLButtonElement | null) => void;
  onKeyDown: (event: ReactKeyboardEvent<HTMLButtonElement>) => void;
  className?: string;
};

function GripButton(props: GripButtonProps): ReactNode {
  const { label, isDragSource, handleRef, gripRef, onKeyDown, className } = props;
  return (
    <Button
      type="button"
      variant="outline"
      size="icon"
      ref={(el) => {
        handleRef(el);
        gripRef(el);
      }}
      className={cn("size-8 shrink-0 cursor-grab touch-none", isDragSource && "cursor-grabbing", className)}
      aria-label={label}
      // prevent native mousedown focus: Chromium re-centers the focused drag handle in the viewport mid-drag and the page jumps
      onMouseDown={(e) => e.preventDefault()}
      onKeyDown={onKeyDown}
    >
      <GripVertical />
    </Button>
  );
}

type FilterGroupBoxProps = NodePosition & { group: FilterGroup; depth: number; groupPath: string };

/** A bordered group with its own rows and footer. The top margin of the buttons is the box border, its padding and the list padding, so they line up with the first row. */
function FilterGroupBox(props: FilterGroupBoxProps): ReactNode {
  const { group, index, join, parentId, path, groupPath, dropEdge, depth, ctx } = props;
  const { labels } = ctx;
  const filterId = group.filterId!; // always assigned by the store; see FilterGroup
  const { ref, handleRef, isDragSource, onGripKeyDown } = useNodeSortable(filterId, props);
  const children = Array.isArray(group.filters) ? group.filters : [];
  const noColumns = ctx.filterableColumns.length === 0;

  return (
    <div
      ref={ref}
      data-grid-filter-group=""
      role="listitem"
      className={cn(
        "relative grid grid-cols-[minmax(4.5rem,auto)_minmax(0,1fr)_auto_auto] items-start gap-1.5 transition-transform",
        isDragSource && "z-10 scale-[1.01] opacity-60 shadow-lg",
      )}
    >
      {dropEdge && <DropIndicator edge={dropEdge} />}
      <ConnectorCell index={index} join={join} parentId={parentId} path={path} ctx={ctx} />
      <div className="flex min-w-0 flex-col gap-2 rounded-md border p-2">
        <FilterList nodes={children} parent={group} depth={depth} path={groupPath} ctx={ctx} />
        <div className="flex items-center gap-2">
          <Button type="button" variant="outline" size="sm" onClick={() => ctx.onAddFilter(group)} disabled={noColumns}>
            {labels.toolbar.addFilter}
          </Button>
          {depth < MAX_FILTER_GROUP_DEPTH && (
            <Button type="button" variant="outline" size="sm" onClick={() => ctx.onAddGroup(group)} disabled={noColumns}>
              {labels.toolbar.addFilterGroup}
            </Button>
          )}
        </div>
      </div>
      <Button type="button" variant="outline" size="icon" className="mt-[calc(--spacing(3)+1px)] size-8 shrink-0" aria-label={labels.toolbar.removeFilterGroupAriaLabel} onClick={() => ctx.onRemove(filterId)}>
        <Trash2 />
      </Button>
      <GripButton label={labels.toolbar.reorderFilterAriaLabel} isDragSource={isDragSource} handleRef={handleRef} gripRef={(el) => ctx.gripRef(filterId, el)} onKeyDown={onGripKeyDown} className="mt-[calc(--spacing(3)+1px)]" />
    </div>
  );
}

type FilterRowProps = NodePosition & { filter: FilterSpec };

/** One filter row: a field select, an operator select, a typed value input, a trash button, and a drag handle. */
function FilterRow(props: FilterRowProps): ReactNode {
  const { filter, index, join, parentId, path, dropEdge, ctx } = props;
  const { labels, columns, filterableColumns, operatorsFor } = ctx;
  const filterId = filter.filterId!; // always assigned by the store; see FilterSpec
  const column = columns.find((c) => c.id === filter.columnId);
  const operators = operatorsFor(column);
  const columnItems = filterableColumns.map((c) => ({ value: c.id, label: columnLabelText(c) }));
  const operatorItems = operators.map((op) => ({ value: op, label: operatorLabel(op, labels.filterOperators) }));
  const { ref, handleRef, isDragSource, onGripKeyDown } = useNodeSortable(filterId, props);

  return (
    <div
      ref={ref}
      data-grid-filter-row=""
      role="listitem"
      className={cn(
        "relative grid grid-cols-[minmax(4.5rem,auto)_minmax(0,1fr)_minmax(0,1fr)_minmax(0,1.5fr)_auto_auto] max-sm:grid-cols-[minmax(4.5rem,auto)_minmax(0,1fr)_auto_auto] items-center gap-1.5 transition-transform",
        isDragSource && "z-10 scale-[1.01] opacity-60 shadow-lg",
      )}
    >
      {dropEdge && <DropIndicator edge={dropEdge} />}
      <ConnectorCell index={index} join={join} parentId={parentId} path={path} ctx={ctx} />
      <Select
        items={columnItems}
        value={filter.columnId}
        onValueChange={(value) => {
          if (value === null) return;
          const nextColumn = columns.find((c) => c.id === value);
          const nextOperators = operatorsFor(nextColumn);
          const nextOperator = nextOperators.includes(filter.operator) ? filter.operator : nextOperators[0];
          ctx.onUpdate(filterId, { columnId: value, operator: nextOperator, value: emptyValueFor(nextOperator) });
        }}
      >
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterColumnAriaLabel}>
          <SelectValue className="truncate" />
        </SelectTrigger>
        <SelectContent>
          {filterableColumns.map((c) => (
            <SelectItem key={c.id} value={c.id}>
              {columnLabelText(c)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Select
        items={operatorItems}
        value={filter.operator}
        onValueChange={(value) => {
          if (value === null) return;
          const nextOperator = value as FilterOperator;
          // each operator family has its own value shape; reset rather than carry a mismatched one
          ctx.onUpdate(filterId, { operator: nextOperator, value: emptyValueFor(nextOperator) });
        }}
      >
        <SelectTrigger className="h-8 w-full max-sm:col-span-3 max-sm:col-start-2" aria-label={labels.toolbar.filterOperatorAriaLabel}>
          <SelectValue className="truncate" />
        </SelectTrigger>
        <SelectContent>
          {operators.map((op) => (
            <SelectItem key={op} value={op}>
              {operatorLabel(op, labels.filterOperators)}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <div className="min-w-0 max-sm:col-span-3 max-sm:col-start-2">
        {operatorHasValue(filter.operator) ? (
          <DataGridFilterValueInput column={column} operator={filter.operator} value={filter.value} onValueChange={(value) => ctx.onUpdate(filterId, { value })} />
        ) : (
          <div className="h-8 w-full rounded border bg-transparent" />
        )}
      </div>
      <Button type="button" variant="outline" size="icon" className="size-8 shrink-0 max-sm:col-start-3 max-sm:row-start-1" aria-label={labels.toolbar.removeFilterAriaLabel} onClick={() => ctx.onRemove(filterId)}>
        <Trash2 />
      </Button>
      <GripButton label={labels.toolbar.reorderFilterAriaLabel} isDragSource={isDragSource} handleRef={handleRef} gripRef={(el) => ctx.gripRef(filterId, el)} onKeyDown={onGripKeyDown} className="max-sm:col-start-4 max-sm:row-start-1" />
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { useDebouncedInput } from "@/registry/default/components/gridcn/use-debounce";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  useDataGridCellTypes,
  useDataGridLabels,
  type AnyColumnDef,
  type FilterOperator,
  type GridCellTypes,
} from "@/registry/default/components/data-grid/data-grid";
import { resolveFilterValueInput, useDataGridInputDebounce, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { distinctColumnValues } from "./distinct-values";
import { useServerFilterValues } from "./server-filter-values";
import { SetFilterList, filterSetOptions, useDebouncedSearch, type SetFilterOption } from "./set-filter-list";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { operatorIsAnyOf, operatorIsBetween } from "./operators-for-column-type";

/** Props for {@link DataGridFilterValueInput}. */
export type DataGridFilterValueInputProps = {
  /** The filtered column; its cell type's `filter.valueInput` (or the type-name default) picks the widget. */
  column: AnyColumnDef | undefined;
  operator: FilterOperator;
  value: string | [string, string] | string[] | undefined;
  onValueChange: (value: string | [string, string] | string[]) => void;
};

/** Debounces a single text/number/date input's keystrokes into one commit, with the provider's `inputDebounceMs`. */
function useFilterInput(value: string, onValueChange: (value: string) => void) {
  const delayMs = useDataGridInputDebounce();
  return useDebouncedInput(value, onValueChange, { delayMs });
}

/** A single debounced text/number/date value input, shared by the plain and `isBetween` (two-input) layouts. */
function SingleValueInput(props: {
  type: "text" | "number" | "date";
  value: string;
  onValueChange: (value: string) => void;
  ariaLabel: string;
  placeholder?: string;
}) {
  const { type, value, onValueChange, ariaLabel, placeholder } = props;
  const { inputProps } = useFilterInput(value, onValueChange);
  return (
    <Input
      type={type}
      {...inputProps}
      placeholder={placeholder}
      aria-label={ariaLabel}
      className="h-8 w-full"
    />
  );
}

/** The `isBetween` two-input range layout. Each side debounces on its own and commits with the other side's typed text. */
function BetweenValueInput(props: {
  type: "text" | "number" | "date";
  from: string;
  to: string;
  onValueChange: (value: [string, string]) => void;
  fromAriaLabel: string;
  toAriaLabel: string;
}) {
  const { type, from, to, onValueChange, fromAriaLabel, toAriaLabel } = props;
  // Each commit sends the other side as the user sees it, pending text included, so two quick edits keep both values.
  const typedFromRef = useRef(from);
  const typedToRef = useRef(to);
  const fromInput = useFilterInput(from, (next) => onValueChange([next, typedToRef.current]));
  const toInput = useFilterInput(to, (next) => onValueChange([typedFromRef.current, next]));
  useEffect(() => {
    typedFromRef.current = fromInput.inputValue;
    typedToRef.current = toInput.inputValue;
  });

  return (
    <div className="flex items-center gap-1.5">
      <Input type={type} {...fromInput.inputProps} aria-label={fromAriaLabel} className="h-8 w-full" />
      <Input type={type} {...toInput.inputProps} aria-label={toAriaLabel} className="h-8 w-full" />
    </div>
  );
}

/**
 * The `isAnyOf` multi-choice input: a dropdown of the select column's own `choices`, each a
 * checkbox. Commits immediately (no debounce — a click is already a deliberate, discrete choice,
 * unlike a keystroke).
 */
function AnyOfValueInput(props: {
  choices: readonly { value: string; label: string }[];
  selected: readonly string[];
  onValueChange: (value: string[]) => void;
  ariaLabel: string;
  summary: string;
}) {
  const { choices, selected, onValueChange, ariaLabel, summary } = props;
  const selectedLower = new Set(selected.map((value) => value.toLowerCase()));
  const toggle = (choice: string, checked: boolean) => {
    const next = new Set(selectedLower);
    if (checked) next.add(choice.toLowerCase());
    else next.delete(choice.toLowerCase());
    const choiceValues = new Set(choices.map((c) => c.value.toLowerCase()));
    // committed order is the column's own, not click order; values outside `choices` stay last
    onValueChange([...choices.map((c) => c.value).filter((v) => next.has(v.toLowerCase())), ...selected.filter((v) => !choiceValues.has(v.toLowerCase()))]);
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button type="button" variant="outline" className="h-8 w-full justify-start font-normal" aria-label={ariaLabel}>
            <span className="truncate">{summary}</span>
          </Button>
        }
      />
      <DropdownMenuContent align="start">
        {choices.map((choice) => (
          <DropdownMenuCheckboxItem
            key={choice.value}
            checked={selectedLower.has(choice.value.toLowerCase())}
            onCheckedChange={(checked) => toggle(choice.value, checked)}
          >
            {choice.label}
          </DropdownMenuCheckboxItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function SetValueBody(props: { column: AnyColumnDef; selected: readonly string[]; onValueChange: (value: string[]) => void }): ReactNode {
  const { column, selected, onValueChange } = props;
  const labels = useDataGridLabels().toolbar;
  const storeApi = useDataGridStoreApi();
  const listId = useId();
  const search = useDebouncedSearch();
  const server = useServerFilterValues(column, search.query);
  const [localOptions] = useState<(SetFilterOption & { text: string })[]>(() =>
    server ? [] : distinctColumnValues(storeApi.getState(), column.id).values.map((value) => (value.key === "" ? { ...value, label: labels.headerFilterBlanks } : value)),
  );
  const options = server ? server.options : localOptions;
  const visible = server ? options : filterSetOptions(options, search.query);
  const serverLine = server?.status === "error" ? labels.headerFilterError : server?.status === "loading" && options.length === 0 ? labels.headerFilterLoading : null;
  const checked = new Set(selected.map((value) => value.toLowerCase()));

  const toggle = (key: string) => {
    const known = new Set(options.map((option) => option.key));
    const next = new Set(checked);
    if (!next.delete(key)) next.add(key);
    onValueChange([...options.filter((option) => next.has(option.key)).map((option) => option.text), ...selected.filter((value) => !known.has(value.toLowerCase()))]);
  };

  return (
    <>
      <Input
        value={search.draft}
        onChange={(event) => search.onChange(event.target.value)}
        placeholder={labels.headerFilterSearchPlaceholder}
        aria-label={labels.headerFilterSearchPlaceholder}
        className="h-8 w-full"
      />
      <SetFilterList key={search.query} options={visible} checked={checked} onToggle={toggle} onEnter={() => {}} idPrefix={listId} ariaLabel={labels.filterValueAriaLabel} />
      {serverLine && (
        <div aria-live="polite" className="text-xs text-muted-foreground">
          {serverLine}
        </div>
      )}
    </>
  );
}

/** The `isAnyOf`/`isNoneOf` input for a column without `choices`: a popover list of the column's distinct values. Values outside the list stay in the selection. */
function SetValueInput(props: { column: AnyColumnDef; selected: readonly string[]; onValueChange: (value: string[]) => void; ariaLabel: string; summary: string }): ReactNode {
  const { ariaLabel, summary, ...body } = props;
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button type="button" variant="outline" className="h-8 w-full justify-start font-normal" aria-label={ariaLabel}>
            <span className="truncate">{summary}</span>
          </Button>
        }
      />
      <PopoverContent align="start" className="w-64">
        <SetValueBody {...body} />
      </PopoverContent>
    </Popover>
  );
}

/**
 * Filter-row value input: renders the widget the filtered column's cell type declares in
 * `filter.valueInput` (a number, date, true/false, choices, or text input, or the type's own
 * component), with a type-name default, and debounces text/number/date keystrokes so typing never
 * triggers a `setFilters` view-index rebuild per character. `isBetween` renders two of the
 * column's typed input side by side instead of one.
 */
export function DataGridFilterValueInput(props: DataGridFilterValueInputProps): ReactNode {
  const { column, operator, value, onValueChange } = props;
  const labels = useDataGridLabels();
  const cellTypes = useDataGridCellTypes();
  const valueInput = column ? resolveFilterValueInput(column, column.type ? cellTypes[column.type] : undefined) : "text";

  if (typeof valueInput !== "string" && column) {
    const CustomInput = valueInput;
    return <CustomInput column={column} operator={operator} value={value} onValueChange={onValueChange} />;
  }
  const inputType = valueInput === "number" ? "number" : valueInput === "date" ? "date" : "text";

  if (operatorIsAnyOf(operator)) {
    const choices = (column?.options as GridCellTypes["select"]["options"] | undefined)?.choices ?? [];
    const selected = Array.isArray(value) ? value : [];
    if (column && choices.length === 0) {
      return (
        <SetValueInput
          column={column}
          selected={selected}
          onValueChange={onValueChange}
          ariaLabel={labels.toolbar.filterValueAriaLabel}
          summary={labels.toolbar.filterValueAnyOfSummary(selected.length)}
        />
      );
    }
    return (
      <AnyOfValueInput
        choices={choices}
        selected={selected}
        onValueChange={onValueChange}
        ariaLabel={labels.toolbar.filterValueAriaLabel}
        summary={labels.toolbar.filterValueAnyOfSummary(selected.length)}
      />
    );
  }

  if (operatorIsBetween(operator)) {
    const [from = "", to = ""] = Array.isArray(value) ? value : ["", ""];
    return (
      <BetweenValueInput
        type={inputType}
        from={from}
        to={to}
        onValueChange={onValueChange}
        fromAriaLabel={labels.toolbar.filterValueFromAriaLabel}
        toAriaLabel={labels.toolbar.filterValueToAriaLabel}
      />
    );
  }

  const textValue = typeof value === "string" ? value : "";

  if (valueInput === "boolean") {
    const booleanItems = [
      { value: "true", label: labels.toolbar.filterValueTrue },
      { value: "false", label: labels.toolbar.filterValueFalse },
    ];
    return (
      <Select items={booleanItems} value={textValue || null} onValueChange={(next) => onValueChange(next ?? "")}>
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterValueAriaLabel}>
          <SelectValue placeholder={labels.toolbar.filterValuePlaceholder} />
        </SelectTrigger>
        <SelectContent>
          {booleanItems.map((item) => (
            <SelectItem key={item.value} value={item.value}>
              {item.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  if (valueInput === "choices") {
    const choices = (column?.options as GridCellTypes["select"]["options"] | undefined)?.choices ?? [];
    return (
      <Select items={choices} value={textValue || null} onValueChange={(next) => onValueChange(next ?? "")}>
        <SelectTrigger className="h-8 w-full" aria-label={labels.toolbar.filterValueAriaLabel}>
          <SelectValue placeholder={labels.toolbar.filterValuePlaceholder} />
        </SelectTrigger>
        <SelectContent>
          {choices.map((choice) => (
            <SelectItem key={choice.value} value={choice.value}>
              {choice.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    );
  }

  return (
    <SingleValueInput
      type={inputType}
      value={textValue}
      onValueChange={onValueChange}
      ariaLabel={labels.toolbar.filterValueAriaLabel}
      placeholder={labels.toolbar.filterValuePlaceholder}
    />
  );
}

"use client";

import { useMemo, type ReactNode } from "react";
import { Settings2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridIsColumnHidden,
  useDataGridLabels,
  type AnyColumnDef,
} from "@/registry/default/components/data-grid/data-grid";
import { columnLabelText, groupPathOf, useDataGridColumnGroupModel, type ColumnGroupModel } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Props for {@link DataGridColumnsMenu}. */
export type DataGridColumnsMenuProps = {
  className?: string;
};

/** One column's visibility row; a separate component so each row subscribes to its own hidden state. */
function ColumnRow(props: { column: AnyColumnDef }): ReactNode {
  const { column } = props;
  const actions = useDataGridActions();
  const hidden = useDataGridIsColumnHidden(column.id);

  return (
    <DropdownMenuCheckboxItem
      checked={!hidden}
      onCheckedChange={(checked) => actions.setColumnHidden(column.id, checked !== true)}
    >
      {columnLabelText(column)}
    </DropdownMenuCheckboxItem>
  );
}

type MenuSection = { key: string; heading: string | null; columns: AnyColumnDef[] };

/** Consecutive columns of the same innermost group form one section, headed by the group path. */
function menuSections(columns: readonly AnyColumnDef[], model: ColumnGroupModel | null): MenuSection[] {
  const sections: MenuSection[] = [];
  for (const column of columns) {
    const path = groupPathOf(model, column.id);
    const key = path.join("/");
    const last = sections.at(-1);
    if (last && last.key === key) {
      last.columns.push(column);
      continue;
    }
    const heading =
      path.length === 0
        ? null
        : path
            .map((id) => {
              const def = model?.groups.get(id)?.def;
              return def?.headerText ?? (typeof def?.header === "string" ? def.header : id);
            })
            .join(" / ");
    sections.push({ key, heading, columns: [column] });
  }
  return sections;
}

/**
 * Show/hide-only column visibility dropdown — pin controls live in the header dropdown /
 * context menu instead. Each row is a
 * `DropdownMenuCheckboxItem` with the standard trailing check-mark indicator, not a square Checkbox.
 */
export function DataGridColumnsMenu(props: DataGridColumnsMenuProps): ReactNode {
  const { className } = props;
  const columns = useDataGridAllColumns();
  const model = useDataGridColumnGroupModel();
  const sections = useMemo(() => menuSections(columns, model), [columns, model]);
  const labels = useDataGridLabels();

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button type="button" variant="outline" size="sm" className={cn(className)} aria-label={labels.toolbar.columnsAriaLabel}>
            <Settings2 />
            {labels.toolbar.columns}
          </Button>
        }
      />
      <DropdownMenuContent data-grid-columns-menu="" align="start" className="w-56">
        {sections.map((section) =>
          section.heading === null ? (
            section.columns.map((column) => <ColumnRow key={column.id} column={column} />)
          ) : (
            <DropdownMenuGroup key={`${section.key}:${section.columns[0]!.id}`}>
              <DropdownMenuLabel>{section.heading}</DropdownMenuLabel>
              {section.columns.map((column) => (
                <ColumnRow key={column.id} column={column} />
              ))}
            </DropdownMenuGroup>
          ),
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import type { FilterOperator } from "@/registry/default/components/data-grid/data-grid";
import type { DataGridFilterOperatorLabels } from "@/registry/default/components/data-grid/data-grid-sdk";

export { operatorsForColumnType } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Human-readable label for a {@link FilterOperator}, for the operator select — reads from {@link useDataGridLabels}'s `filterOperators` group. */
export function operatorLabel(operator: FilterOperator, labels: DataGridFilterOperatorLabels): string {
  return labels[operator];
}

/** Whether `operator` takes a value input at all (`empty`/`notEmpty` don't); `isBetween` renders two. */
export function operatorHasValue(operator: FilterOperator): boolean {
  return operator !== "empty" && operator !== "notEmpty";
}

/** Whether `operator` needs the two-input `isBetween` range layout instead of a single value input. */
export function operatorIsBetween(operator: FilterOperator): boolean {
  return operator === "isBetween";
}

/** The empty filter value for `operator`: a list for `isAnyOf` / `isNoneOf`, a from/to pair for `isBetween`, otherwise text. */
export function emptyValueFor(operator: FilterOperator | undefined): string | [string, string] | string[] {
  if (operator === "isAnyOf" || operator === "isNoneOf") return [];
  if (operator === "isBetween") return ["", ""];
  return "";
}

/** Whether `operator` takes a multi-value choice list (`isAnyOf` / `isNoneOf`) rather than a single text input. */
export function operatorIsAnyOf(operator: FilterOperator): boolean {
  return operator === "isAnyOf" || operator === "isNoneOf";
}

"use client";

import { useId, useMemo, useRef, useState, type KeyboardEvent, type ReactNode, type RefObject } from "react";
import { Filter } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { useDataGridActions, useDataGridApi, useDataGridCellTypes, useDataGridLabels, type AnyColumnDef } from "@/registry/default/components/data-grid/data-grid";
import {
  GRID_ATTR,
  columnLabelText,
  forEachFilterSpec,
  isComposingKey,
  isFilterGroup,
  pruneFilterSpecs,
  resolveFilterOperators,
  useDataGridIsColumnFiltered,
  useDataGridStoreApi,
} from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_SET_FILTER_ENTRIES, checkedKeysFromFilters, planServerSetFilter, planSetFilter } from "./apply-set-filter";
import { distinctColumnValues, isOwnSetFilter } from "./distinct-values";
import { useServerFilterValues, useServerFilterValuesEnabled } from "./server-filter-values";
import { SetFilterList, filterSetOptions, useDebouncedSearch, type SetFilterOption } from "./set-filter-list";

/** Props for {@link DataGridHeaderFilter} — matches the core's `renderHeaderFilter` render-prop ctx exactly. */
export type DataGridHeaderFilterProps = {
  column: AnyColumnDef;
  index: number;
};

function HeaderFilterBody(props: { column: AnyColumnDef; onClose: () => void; searchRef: RefObject<HTMLInputElement | null> }): ReactNode {
  const { column, onClose, searchRef } = props;
  const labels = useDataGridLabels().toolbar;
  const cellTypes = useDataGridCellTypes();
  const storeApi = useDataGridStoreApi();
  const actions = useDataGridActions();
  const filtered = useDataGridIsColumnFiltered(column.id);
  const listId = useId();
  const listRef = useRef<HTMLDivElement>(null);

  const serverEnabled = useServerFilterValuesEnabled(column);
  const [loaded] = useState(() => {
    const state = storeApi.getState();
    let inGroup = false;
    for (const node of state.filterState) {
      if (isFilterGroup(node)) forEachFilterSpec([node], (f) => void (inGroup = inGroup || f.columnId === column.id));
    }
    if (serverEnabled) {
      return { values: [], capped: false, hasHoles: false, inGroup, partial: false, keys: [] as string[], texts: new Map<string, string>(), openFilters: state.filterState, initiallyChecked: new Set<string>() };
    }
    const distinct = distinctColumnValues(state, column.id);
    const keys = distinct.values.map((value) => value.key);
    const texts = new Map(distinct.values.map((value) => [value.key, value.text]));
    return { ...distinct, inGroup, partial: distinct.hasHoles || state.sortMode === "server" || state.filterMode === "server", keys, texts, openFilters: state.filterState, initiallyChecked: checkedKeysFromFilters(state.filterState, column.id, keys) };
  });
  const search = useDebouncedSearch();
  const { query } = search;
  const [overrides, setOverrides] = useState<ReadonlyMap<string, boolean>>(() => new Map());
  const server = useServerFilterValues(column, query, overrides);
  const localOptions = useMemo<SetFilterOption[]>(
    () => loaded.values.map((value) => (value.key === "" ? { ...value, label: labels.headerFilterBlanks } : value)),
    [loaded.values, labels.headerFilterBlanks],
  );
  const options: readonly SetFilterOption[] = server ? server.options : localOptions;

  const known = server ? server.known : loaded.texts;
  const checked = useMemo<ReadonlySet<string>>(() => {
    // A server list may be partial, so without a set entry nothing starts checked.
    const hasEntry = loaded.openFilters.some((node) => isOwnSetFilter(node, column.id));
    const next = server ? (hasEntry ? checkedKeysFromFilters(loaded.openFilters, column.id, [...known.keys()]) : new Set<string>()) : new Set(loaded.initiallyChecked);
    for (const [key, on] of overrides) {
      if (on) next.add(key);
      else next.delete(key);
    }
    return next;
  }, [server, known, loaded.openFilters, loaded.initiallyChecked, column.id, overrides]);
  const [applyBlocked, setApplyBlocked] = useState(false);
  const visible = useMemo(() => (server ? options : filterSetOptions(options, query)), [server, options, query]);
  const checkedVisible = visible.reduce((count, option) => count + (checked.has(option.key) ? 1 : 0), 0);

  const allowed = resolveFilterOperators(column, cellTypes[column.type ?? "text"]);
  const planFor = (filters: typeof loaded.openFilters) =>
    server
      ? planServerSetFilter({ filters, columnId: column.id, known, checked, allowed })
      : planSetFilter({ filters, columnId: column.id, keys: loaded.keys, texts: loaded.texts, checked, allowed });
  const plan = planFor(loaded.openFilters);
  const tooMany = applyBlocked || (plan.status === "blocked" && plan.reason === "too-many");
  const canApply = plan.status !== "blocked";

  const toggle = (key: string) => {
    setApplyBlocked(false);
    setOverrides((current) => new Map(current).set(key, !checked.has(key)));
  };

  const toggleVisible = () => {
    setApplyBlocked(false);
    const typed = server ? options : filterSetOptions(options, search.draft);
    const allChecked = typed.length > 0 && typed.every((option) => checked.has(option.key));
    setOverrides((current) => {
      const next = new Map(current);
      for (const option of typed) next.set(option.key, !allChecked);
      return next;
    });
  };

  const apply = () => {
    if (!canApply) return;
    const state = storeApi.getState();
    const fresh = planFor(state.filterState);
    if (fresh.status === "blocked") {
      setApplyBlocked(true);
      return;
    }
    if (fresh.status === "apply") actions.setFilters(fresh.filters);
    onClose();
  };

  const clear = () => {
    actions.setFilters(pruneFilterSpecs(storeApi.getState().filterState, (filter) => filter.columnId !== column.id));
    onClose();
  };

  const onSearchKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (isComposingKey(event)) return;
    if (event.key === "ArrowDown" && visible.length > 0) {
      event.preventDefault();
      listRef.current?.focus();
    } else if (event.key === "Enter") {
      event.preventDefault();
      apply();
    }
  };

  const serverLine = server?.status === "error" ? labels.headerFilterError : server?.status === "loading" && server.options.length === 0 ? labels.headerFilterLoading : null;
  const status = serverLine ?? (tooMany ? labels.headerFilterTooManySelected(MAX_SET_FILTER_ENTRIES) : (server ? server.capped : loaded.capped) ? labels.headerFilterCapped : labels.headerFilterSelectedCount(checkedVisible, visible.length));
  const selectAllState = visible.length > 0 && checkedVisible === visible.length ? true : checkedVisible > 0 ? "mixed" : false;

  return (
    <>
      <InputGroup>
        <InputGroupAddon align="inline-start" onClick={() => searchRef.current?.focus()}>
          <Checkbox
            aria-label={labels.headerFilterSelectAll}
            checked={selectAllState === true}
            indeterminate={selectAllState === "mixed"}
            onCheckedChange={toggleVisible}
            onClick={(event) => event.stopPropagation()}
          />
        </InputGroupAddon>
        <InputGroupInput
          ref={searchRef}
          value={search.draft}
          onChange={(event) => search.onChange(event.target.value)}
          onKeyDown={onSearchKeyDown}
          placeholder={labels.headerFilterSearchPlaceholder}
          aria-label={labels.headerFilterSearchPlaceholder}
        />
      </InputGroup>
      <SetFilterList key={query} options={visible} checked={checked} onToggle={toggle} onEnter={apply} idPrefix={listId} ariaLabel={columnLabelText(column)} listRef={listRef} />
      <div aria-live="polite" className={cn("text-xs text-muted-foreground", tooMany && "text-destructive")}>
        <bdi>{status}</bdi>
      </div>
      {loaded.partial && <div className="text-xs text-muted-foreground">{labels.headerFilterLoadedRowsOnly}</div>}
      {loaded.inGroup && <div className="text-xs text-muted-foreground">{labels.headerFilterGroupRows}</div>}
      <div className="flex justify-end gap-2">
        <Button type="button" variant="outline" size="sm" disabled={!filtered} onClick={clear}>
          {labels.headerFilterClear}
        </Button>
        <Button type="button" size="sm" disabled={!canApply} onClick={apply}>
          {labels.headerFilterApply}
        </Button>
      </div>
    </>
  );
}

/**
 * The per-column set filter: a header button that opens a popover with a searchable, countable
 * list of the column's distinct values. Wire via
 * `<DataGridRoot renderHeaderFilter={(ctx) => <DataGridHeaderFilter {...ctx} />}>`.
 */
export function DataGridHeaderFilter(props: DataGridHeaderFilterProps): ReactNode {
  const { column } = props;
  const labels = useDataGridLabels().toolbar;
  const filtered = useDataGridIsColumnFiltered(column.id);
  const api = useDataGridApi();
  const [open, setOpen] = useState(false);
  const keyboardOpenedRef = useRef(false);
  const searchRef = useRef<HTMLInputElement>(null);
  const columnLabel = columnLabelText(column);

  return (
    <Popover
      open={open}
      onOpenChange={(next, details) => {
        if (next) keyboardOpenedRef.current = (details.event?.target as HTMLElement | null)?.hasAttribute(GRID_ATTR.keyboardOpen) ?? false;
        setOpen(next);
      }}
    >
      <PopoverTrigger
        render={
          <button
            type="button"
            data-grid-header-filter-trigger=""
            tabIndex={-1}
            aria-label={labels.headerFilterAriaLabel(columnLabel, filtered)}
            className={cn("shrink-0 rounded p-0.5 pointer-coarse:p-[5px] text-muted-foreground outline-hidden hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring/50", filtered && "text-primary")}
          >
            <Filter className={cn("size-3.5", filtered && "fill-current")} />
          </button>
        }
      />
      <PopoverContent
        data-grid-header-filter-popup=""
        align="start"
        initialFocus={searchRef}
        aria-label={labels.headerFilterAriaLabel(columnLabel, false)}
        className="w-64"
        onContextMenu={(event) => event.stopPropagation()}
        finalFocus={() => {
          if (!keyboardOpenedRef.current) return true;
          const active = document.activeElement;
          const focusIsFree = !active || active === document.body || active.closest("[data-grid-header-filter-popup], [data-grid-header-filter-trigger]") !== null;
          if (focusIsFree) api.focus();
          return false;
        }}
      >
        <HeaderFilterBody column={column} onClose={() => setOpen(false)} searchRef={searchRef} />
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { memo, useCallback, useEffect, useRef, useState, type KeyboardEvent, type ReactNode, type Ref } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { cn } from "@/lib/utils";
import { useDataGridInputDebounce } from "@/registry/default/components/data-grid/data-grid-sdk";
import { useDebounce } from "@/registry/default/components/gridcn/use-debounce";

export const SET_FILTER_ROW_HEIGHT = 28;
const OVERSCAN = 8;
const VIEWPORT_ROWS = 8;
const VIEWPORT_HEIGHT = SET_FILTER_ROW_HEIGHT * VIEWPORT_ROWS;

const countFormat = new Intl.NumberFormat("en-US");

export type SetFilterOption = { key: string; label: string; count?: number };

/** A search box value plus its debounced `query`, waiting the provider's `inputDebounceMs`. */
export function useDebouncedSearch() {
  const delayMs = useDataGridInputDebounce();
  const [draft, onChange] = useState("");
  const query = useDebounce(draft, delayMs);
  return { draft, query, onChange };
}

/** The options whose label contains `query`, compared as plain case-insensitive text. */
export function filterSetOptions(options: readonly SetFilterOption[], query: string): readonly SetFilterOption[] {
  const needle = query.toLowerCase();
  return needle === "" ? options : options.filter((option) => option.label.toLowerCase().includes(needle));
}

export type SetFilterListProps = {
  options: readonly SetFilterOption[];
  checked: ReadonlySet<string>;
  onToggle: (key: string) => void;
  onEnter: () => void;
  idPrefix: string;
  ariaLabel: string;
  className?: string;
  listRef?: Ref<HTMLDivElement>;
};

/** Virtualized multi-select listbox with fixed-height rows; only the rows near the viewport mount. */
export function SetFilterList(props: SetFilterListProps): ReactNode {
  const { options, checked, onToggle, onEnter, idPrefix, ariaLabel, className, listRef } = props;
  const [scrollTop, setScrollTop] = useState(0);
  const [activeIndex, setActiveIndex] = useState(0);
  const lastIndex = options.length - 1;
  const active = Math.min(activeIndex, Math.max(lastIndex, 0));

  const first = Math.max(0, Math.floor(scrollTop / SET_FILTER_ROW_HEIGHT) - OVERSCAN);
  const last = Math.min(lastIndex, Math.ceil((scrollTop + VIEWPORT_HEIGHT) / SET_FILTER_ROW_HEIGHT) + OVERSCAN);
  const optionId = (index: number) => `${idPrefix}-option-${index}`;

  const reveal = (list: HTMLElement, index: number) => {
    const top = index * SET_FILTER_ROW_HEIGHT;
    if (top < list.scrollTop) list.scrollTop = top;
    else if (top + SET_FILTER_ROW_HEIGHT > list.scrollTop + VIEWPORT_HEIGHT) list.scrollTop = top + SET_FILTER_ROW_HEIGHT - VIEWPORT_HEIGHT;
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const move = (to: number) => {
      event.preventDefault();
      const next = Math.min(Math.max(to, 0), lastIndex);
      setActiveIndex(next);
      reveal(event.currentTarget, next);
    };
    switch (event.key) {
      case "ArrowDown":
        return move(active + 1);
      case "ArrowUp":
        return move(active - 1);
      case "Home":
        return move(0);
      case "End":
        return move(lastIndex);
      case " ": {
        event.preventDefault();
        const option = options[active];
        if (option) onToggle(option.key);
        return;
      }
      case "Enter":
        event.preventDefault();
        onEnter();
        return;
    }
  };

  const toggleRef = useRef(onToggle);
  useEffect(() => {
    toggleRef.current = onToggle;
  });
  const select = useCallback((index: number, key: string) => {
    setActiveIndex(index);
    toggleRef.current(key);
  }, []);

  const rows = Array.from({ length: Math.max(0, last - first + 1) }, (_, offset) => {
    const index = first + offset;
    const option = options[index]!;
    return (
      <SetFilterRow
        key={option.key}
        id={optionId(index)}
        optionKey={option.key}
        label={option.label}
        count={option.count}
        index={index}
        setSize={options.length}
        selected={checked.has(option.key)}
        isActive={index === active}
        onSelect={select}
      />
    );
  });

  return (
    <div
      ref={listRef}
      role="listbox"
      tabIndex={0}
      aria-label={ariaLabel}
      aria-multiselectable="true"
      aria-activedescendant={active >= first && active <= last ? optionId(active) : undefined}
      className={cn("relative overflow-y-auto rounded-md border border-input outline-hidden focus-visible:ring-2 focus-visible:ring-ring/50", className)}
      style={{ height: VIEWPORT_HEIGHT }}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      onKeyDown={handleKeyDown}
    >
      <div className="relative" style={{ height: options.length * SET_FILTER_ROW_HEIGHT }}>
        {rows}
      </div>
    </div>
  );
}

type SetFilterRowProps = {
  id: string;
  optionKey: string;
  label: string;
  count: number | undefined;
  index: number;
  setSize: number;
  selected: boolean;
  isActive: boolean;
  onSelect: (index: number, key: string) => void;
};

const SetFilterRow = memo(function SetFilterRow({ id, optionKey, label, count, index, setSize, selected, isActive, onSelect }: SetFilterRowProps) {
  return (
    <div
      id={id}
      role="option"
      aria-selected={selected}
      aria-setsize={setSize}
      aria-posinset={index + 1}
      data-active={isActive || undefined}
      className="absolute inset-x-0 flex cursor-default items-center gap-2 rounded-sm px-1.5 text-sm data-[active]:bg-accent data-[active]:text-accent-foreground"
      style={{ top: index * SET_FILTER_ROW_HEIGHT, height: SET_FILTER_ROW_HEIGHT }}
      onMouseDown={(event) => event.preventDefault()}
      onClick={() => onSelect(index, optionKey)}
    >
      <Checkbox checked={selected} tabIndex={-1} aria-hidden className="pointer-events-none" />
      <span className="min-w-0 flex-1 truncate">{label}</span>
      <span className="min-w-14 shrink-0 text-end text-xs text-muted-foreground tabular-nums">{count === undefined ? null : countFormat.format(count)}</span>
    </div>
  );
});

import type { FilterNode, FilterOperator, FilterSpec } from "@/registry/default/components/data-grid/data-grid";
import { isFilterGroup } from "@/registry/default/components/data-grid/data-grid-sdk";

export const MAX_SET_FILTER_ENTRIES = 1000;

type SetOperator = "isAnyOf" | "isNoneOf";

export type SetFilterPlan =
  | { status: "unchanged" }
  | { status: "blocked"; reason: "none-checked" | "too-many" }
  | { status: "apply"; filters: FilterNode[] };

export type SetFilterPlanInput = {
  /** Only the top-level set rows of `columnId` are the header filter's; set rows inside a group belong to the filter menu. */
  filters: readonly FilterNode[];
  columnId: string;
  keys: readonly string[];
  /** Original text per key, written into the filter values; a key without an entry is written as is. */
  texts?: ReadonlyMap<string, string>;
  checked: ReadonlySet<string>;
  allowed: readonly FilterOperator[];
};

const isSetFilterOf = (node: FilterNode, columnId: string): node is FilterSpec =>
  !isFilterGroup(node) && node.columnId === columnId && (node.operator === "isAnyOf" || node.operator === "isNoneOf");

const listOf = (filter: FilterSpec): string[] => (Array.isArray(filter.value) ? (filter.value as string[]) : []);

export function checkedKeysFromFilters(filters: readonly FilterNode[], columnId: string, keys: readonly string[]): Set<string> {
  const entries = filters.filter((f): f is FilterSpec => isSetFilterOf(f, columnId)).map((f) => ({ operator: f.operator, values: new Set(listOf(f).map((v) => v.toLowerCase())) }));
  const checked = new Set<string>();
  for (const key of keys) {
    if (entries.every((e) => (e.operator === "isAnyOf") === e.values.has(key))) checked.add(key);
  }
  return checked;
}

function chooseOperator(checkedCount: number, uncheckedCount: number, allowed: readonly FilterOperator[], existing: SetOperator | undefined): SetOperator {
  const canAny = allowed.includes("isAnyOf");
  const canNone = allowed.includes("isNoneOf");
  if (!canNone) return "isAnyOf";
  if (!canAny) return "isNoneOf";
  if (checkedCount !== uncheckedCount) return checkedCount < uncheckedCount ? "isAnyOf" : "isNoneOf";
  return existing ?? "isAnyOf";
}

const sameList = (a: readonly string[], b: readonly string[]) => {
  const left = new Set(a.map((v) => v.toLowerCase()));
  const right = new Set(b.map((v) => v.toLowerCase()));
  return left.size === right.size && [...left].every((v) => right.has(v));
};

const outsideValues = (entries: readonly FilterSpec[], known: ReadonlySet<string>): string[] => entries.flatMap(listOf).filter((v) => !known.has(v.toLowerCase()));

/** The entry that keeps hiding values outside the list when every listed value is checked, or none. */
function keepOutsideValues(existing: readonly FilterSpec[], columnId: string, keys: readonly string[], known: ReadonlySet<string>): FilterSpec | undefined {
  const anyOutside = outsideValues(existing.filter((f) => f.operator === "isAnyOf"), known);
  if (anyOutside.length > 0) return { columnId, operator: "isAnyOf", value: [...keys, ...anyOutside] };
  const noneOutside = outsideValues(existing.filter((f) => f.operator === "isNoneOf"), known);
  return noneOutside.length > 0 ? { columnId, operator: "isNoneOf", value: noneOutside } : undefined;
}

/** Replaces the column's set entries with `entry` at the first one's position (or appends it); `undefined` removes them. */
function placeSetEntry(filters: readonly FilterNode[], existing: readonly FilterSpec[], entry: FilterSpec | undefined): SetFilterPlan {
  if (!entry) return existing.length === 0 ? { status: "unchanged" } : { status: "apply", filters: filters.filter((f) => !existing.includes(f as FilterSpec)) };
  if (existing.length === 1 && existing[0]!.operator === entry.operator && sameList(listOf(existing[0]!), entry.value as string[])) return { status: "unchanged" };

  const next: FilterNode[] = [];
  let placed = false;
  for (const filter of filters) {
    if (!existing.includes(filter as FilterSpec)) next.push(filter);
    else if (!placed) {
      next.push(entry);
      placed = true;
    }
  }
  if (!placed) next.push(entry);
  return { status: "apply", filters: next };
}

/**
 * Plans the `setFilters` write for one column's set filter: replaces every `isAnyOf`/`isNoneOf`
 * entry of the column with the shorter of the checked and unchecked lists, using only operators
 * the column allows, and keeps every other filter.
 */
export function planSetFilter(input: SetFilterPlanInput): SetFilterPlan {
  const { filters, columnId, keys, checked, allowed } = input;
  const textOf = (key: string) => input.texts?.get(key) ?? key;
  const existing = filters.filter((f): f is FilterSpec => isSetFilterOf(f, columnId));
  const checkedKeys = keys.filter((key) => checked.has(key));
  const uncheckedKeys = keys.filter((key) => !checked.has(key));

  if (checkedKeys.length === 0) return { status: "blocked", reason: "none-checked" };

  const known = new Set(keys);
  let entry: FilterSpec | undefined;
  if (uncheckedKeys.length === 0) {
    entry = keepOutsideValues(existing, columnId, keys.map(textOf), known);
    if (entry && entry.value!.length > MAX_SET_FILTER_ENTRIES) return { status: "blocked", reason: "too-many" };
  } else {
    const operator = chooseOperator(checkedKeys.length, uncheckedKeys.length, allowed, existing[0]?.operator as SetOperator | undefined);
    const outside = existing.length === 1 && existing[0]!.operator === operator ? outsideValues(existing, known) : [];
    const value = [...(operator === "isAnyOf" ? checkedKeys : uncheckedKeys).map(textOf), ...outside];
    if (value.length > MAX_SET_FILTER_ENTRIES) return { status: "blocked", reason: "too-many" };
    entry = { columnId, operator, value };
  }

  return placeSetEntry(filters, existing, entry);
}

export type ServerSetFilterPlanInput = {
  filters: readonly FilterNode[];
  columnId: string;
  /** Every value a server list showed so far, by key to original text; the full value set is unknown. */
  known: ReadonlyMap<string, string>;
  checked: ReadonlySet<string>;
  allowed: readonly FilterOperator[];
};

/**
 * Plans the write for a set filter over a server value list. The list may be partial, so the entry
 * lists the checked texts (`isAnyOf`), or the unchecked texts when the column already holds one
 * `isNoneOf` entry. Existing values the lists never showed stay.
 */
export function planServerSetFilter(input: ServerSetFilterPlanInput): SetFilterPlan {
  const { filters, columnId, known, checked, allowed } = input;
  const existing = filters.filter((f): f is FilterSpec => isSetFilterOf(f, columnId));
  const operator: SetOperator = existing.length === 1 && existing[0]!.operator === "isNoneOf" && allowed.includes("isNoneOf") ? "isNoneOf" : "isAnyOf";
  const picked = [...known].filter(([key]) => checked.has(key) === (operator === "isAnyOf")).map(([, text]) => text);
  const outside = existing.length === 1 && existing[0]!.operator === operator ? outsideValues(existing, new Set(known.keys())) : [];
  const value = [...picked, ...outside];
  if (value.length > MAX_SET_FILTER_ENTRIES) return { status: "blocked", reason: "too-many" };
  if (operator === "isAnyOf" && value.length === 0) return { status: "blocked", reason: "none-checked" };
  return placeSetEntry(filters, existing, value.length === 0 ? undefined : { columnId, operator, value });
}

import type { CellType, DataGridReadState, FilterNode } from "@/registry/default/components/data-grid/data-grid";
import { displayText, isFilterGroup, makeFilterPredicate, rowAccessorFor, toSafeText } from "@/registry/default/components/data-grid/data-grid-sdk";

export const DISTINCT_VALUES_CAP = 100_000;

/** `key` is the lowercased text the matcher groups by; `text` is the first-seen original text a filter entry stores. */
export type DistinctValue = { key: string; text: string; label: string; count: number };

export type DistinctValues = { values: DistinctValue[]; capped: boolean; hasHoles: boolean };

export type DistinctValuesInput = Pick<DataGridReadState, "data" | "columns" | "cellTypes" | "filterState"> & { filterMode?: "client" | "server" };

export const isOwnSetFilter = (node: FilterNode, columnId: string) =>
  !isFilterGroup(node) && node.columnId === columnId && (node.operator === "isAnyOf" || node.operator === "isNoneOf");

function labelFor(cellType: CellType | undefined, raw: unknown, options: unknown): string {
  if (!cellType) return toSafeText(raw);
  try {
    return toSafeText(displayText(cellType, raw, options));
  } catch {
    return toSafeText(raw);
  }
}

/**
 * Counts the distinct values of `columnId`, grouped by the lowercased text the filter matcher sees.
 * Rows count when they pass every other top-level node; the column's own top-level set rows never
 * hide its own values, and a set row of the column inside a group counts as any other filter. Lazy holes are skipped and reported as `hasHoles`. Past {@link DISTINCT_VALUES_CAP} keys,
 * new keys stop counting and `capped` is set.
 */
export function distinctColumnValues(state: DistinctValuesInput, columnId: string): DistinctValues {
  const column = state.columns.find((c) => c.id === columnId);
  if (!column) return { values: [], capped: false, hasHoles: false };
  const { data } = state;
  const accessor = rowAccessorFor(state.columns, data, state.cellTypes);
  const passes = makeFilterPredicate(accessor, (state.filterMode === "server" ? [] : state.filterState).filter((node) => !isOwnSetFilter(node, columnId)));

  const groups = new Map<string, { row: number; text: string; count: number }>();
  let capped = false;
  let hasHoles = false;
  for (let row = 0; row < data.length; row++) {
    if (data[row] === undefined) {
      hasHoles = true;
      continue;
    }
    if (!passes(row)) continue;
    const text = accessor.getText(row, columnId);
    const key = text.toLowerCase();
    const group = groups.get(key);
    if (group) group.count++;
    else if (groups.size < DISTINCT_VALUES_CAP) groups.set(key, { row, text, count: 1 });
    else capped = true;
  }

  const cellType = column.type ? state.cellTypes[column.type] : undefined;
  const values: (DistinctValue & { row: number })[] = [];
  for (const [key, { row, text, count }] of groups) {
    values.push({ key, text, label: labelFor(cellType, accessor.getValue?.(row, columnId), column.options), count, row });
  }
  const compare = accessor.compare?.(columnId);
  values.sort(compare ? (a, b) => compare(a.row, b.row) : (a, b) => a.label.localeCompare(b.label));
  return { values: values.map(({ key, text, label, count }) => ({ key, text, label, count })), capped, hasHoles };
}

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { useDataGridLabels, type AnyColumnDef } from "@/registry/default/components/data-grid/data-grid";
import { useDataGridSelector, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_SET_FILTER_ENTRIES } from "./apply-set-filter";
import { isOwnSetFilter } from "./distinct-values";
import type { SetFilterOption } from "./set-filter-list";

const MAX_LABEL_LENGTH = 1000;

export type ServerFilterOption = SetFilterOption & { text: string };

export type ServerFilterValues = {
  /** `"loading"` keeps the previous `options` while a new search runs; `"error"` keeps them too. */
  status: "loading" | "ready" | "error";
  options: readonly ServerFilterOption[];
  /** Key to text of every value an answer showed since the first request: a search narrows `options`, not this. */
  known: ReadonlyMap<string, string>;
  capped: boolean;
};

/** Adds `options` to `known` and drops the first-seen entries beyond `MAX_SET_FILTER_ENTRIES`, never one of `options` or `pinned`. */
export function mergeKnownValues(
  known: ReadonlyMap<string, string>,
  options: readonly ServerFilterOption[],
  pinned: ReadonlyMap<string, unknown> = new Map(),
): Map<string, string> {
  const merged = new Map(known);
  for (const option of options) merged.set(option.key, option.text);
  const current = new Set(options.map((option) => option.key));
  for (const key of merged.keys()) {
    if (merged.size <= MAX_SET_FILTER_ENTRIES) break;
    if (!current.has(key) && !pinned.has(key)) merged.delete(key);
  }
  return merged;
}

/** Reads an untrusted provider response: string labels only, one entry per lowercase key, at most {@link MAX_SET_FILTER_ENTRIES}. `null` when the shape is wrong. */
export function sanitizeServerValues(response: unknown): { options: ServerFilterOption[]; capped: boolean } | null {
  const values = (response as { values?: unknown } | null)?.values;
  if (!Array.isArray(values)) return null;
  const byKey = new Map<string, ServerFilterOption>();
  let capped = false;
  for (const entry of values) {
    const label = (entry as { label?: unknown } | null)?.label;
    if (typeof label !== "string") continue;
    const text = label.slice(0, MAX_LABEL_LENGTH);
    const key = text.toLowerCase();
    if (byKey.has(key)) continue;
    if (byKey.size >= MAX_SET_FILTER_ENTRIES) {
      capped = true;
      break;
    }
    const count = (entry as { count?: unknown }).count;
    byKey.set(key, { key, label: text, text, count: typeof count === "number" && Number.isSafeInteger(count) && count >= 0 ? count : undefined });
  }
  return { options: [...byKey.values()], capped };
}

const hasChoices = (column: AnyColumnDef): boolean => {
  const choices = (column.options as { choices?: unknown } | undefined)?.choices;
  return Array.isArray(choices) && choices.length > 0;
};

/** Whether the set-value lists of `column` come from `fetchFilterValues`; a column with declared choices never does. */
export function useServerFilterValuesEnabled(column: AnyColumnDef): boolean {
  return useDataGridSelector((s) => s.fetchFilterValues !== undefined) && !hasChoices(column);
}

/**
 * The server set values of `column` for `search`, or `null` when the provider is absent or the column has
 * `choices`. A new `search`, a column switch, and unmount abort the request in flight; a stale result is dropped.
 */
export function useServerFilterValues(column: AnyColumnDef, search: string, pinned?: ReadonlyMap<string, unknown>): ServerFilterValues | null {
  const enabled = useServerFilterValuesEnabled(column);
  const storeApi = useDataGridStoreApi();
  const blanks = useDataGridLabels().toolbar.headerFilterBlanks;
  const [result, setResult] = useState<ServerFilterValues>({ status: "loading", options: [], known: new Map(), capped: false });
  const columnId = column.id;
  const pinnedRef = useRef(pinned);
  useLayoutEffect(() => {
    pinnedRef.current = pinned;
  });

  useEffect(() => {
    if (!enabled) return;
    const controller = new AbortController();
    setResult((previous) => ({ ...previous, status: "loading" }));
    void (async () => {
      try {
        const state = storeApi.getState();
        const fetchValues = state.fetchFilterValues;
        if (!fetchValues) return;
        const filters = state.filterState.filter((node) => !isOwnSetFilter(node, columnId));
        const response = await fetchValues({ columnId, search, filters, signal: controller.signal });
        if (controller.signal.aborted) return;
        const clean = sanitizeServerValues(response);
        if (!clean) {
          setResult((previous) => ({ ...previous, status: "error" }));
          return;
        }
        setResult((previous) => ({
          status: "ready",
          capped: clean.capped,
          options: clean.options,
          known: mergeKnownValues(previous.known, clean.options, pinnedRef.current),
        }));
      } catch {
        if (!controller.signal.aborted) setResult((previous) => ({ ...previous, status: "error" }));
      }
    })();
    return () => controller.abort();
  }, [enabled, storeApi, columnId, search]);

  const options = useMemo(
    () => result.options.map((option) => (option.key === "" ? { ...option, label: blanks } : option)),
    [result.options, blanks],
  );
  return enabled ? { ...result, options } : null;
}
